using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Drawing;
using System.Diagnostics;
using System.Threading;
using System.Threading.Tasks;
using System.Collections.Generic;
namespace kok {
 public static class LocalOcr {
  public static async Task<Dictionary<string,object>> Read(byte[] image,string appDir,string workDir,CancellationToken token){
   if(image==null||image.Length>16*1024*1024)throw new InvalidDataException("OCR image exceeds its size limit.");Directory.CreateDirectory(workDir);string id=Guid.NewGuid().ToString("N"),input=Path.Combine(workDir,id+".png"),output=Path.Combine(workDir,id+".json");
   try{using(var stream=new MemoryStream(image))using(var source=Image.FromStream(stream)){if((long)source.Width*source.Height>40000000)throw new InvalidDataException("OCR image dimensions exceed the limit.");double scale=Math.Min(1,2500d/Math.Max(source.Width,source.Height));using(var bitmap=new Bitmap(Math.Max(1,(int)(source.Width*scale)),Math.Max(1,(int)(source.Height*scale))))using(var graphics=Graphics.FromImage(bitmap)){graphics.Clear(Color.White);graphics.DrawImage(source,0,0,bitmap.Width,bitmap.Height);bitmap.Save(input,System.Drawing.Imaging.ImageFormat.Png);}}
    string helper=Path.Combine(appDir,"ui","modules","ocr-windows.ps1"),shell=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"WindowsPowerShell","v1.0","powershell.exe");if(!File.Exists(helper))throw new IOException("The offline Windows OCR helper is missing.");var start=new ProcessStartInfo{FileName=shell,Arguments="-NoLogo -NoProfile -NonInteractive -ExecutionPolicy Bypass -File \""+helper+"\" -InputFile \""+input+"\" -OutputFile \""+output+"\"",WorkingDirectory=Path.GetFullPath(workDir),UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};foreach(var key in start.EnvironmentVariables.Keys.Cast<string>().Where(k=>!new[]{"SYSTEMROOT","SYSTEMDRIVE","PROGRAMDATA","WINDIR","PATH","TEMP","TMP","USERPROFILE","LOCALAPPDATA"}.Contains(k.ToUpperInvariant())).ToArray())start.EnvironmentVariables.Remove(key);
    using(var process=Process.Start(start))using(var timeout=CancellationTokenSource.CreateLinkedTokenSource(token)){timeout.CancelAfter(60000);var stdout=process.StandardOutput.ReadToEndAsync();var stderr=process.StandardError.ReadToEndAsync();using(timeout.Token.Register(()=>{try{if(!process.HasExited)process.Kill();}catch{}})){await Task.Run(()=>process.WaitForExit(),CancellationToken.None);token.ThrowIfCancellationRequested();if(timeout.IsCancellationRequested)throw new IOException("Offline OCR timed out.");await stdout;await stderr;if(process.ExitCode!=0||!File.Exists(output))throw new IOException("Windows OCR is unavailable. Install an OCR language in Windows settings and retry.");if(new FileInfo(output).Length>2*1024*1024)throw new InvalidDataException("OCR output exceeds its size limit.");return Library.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(output,Encoding.UTF8));}}
   }finally{if(File.Exists(input))File.Delete(input);if(File.Exists(output))File.Delete(output);}
  }
 }
 public partial class Library {
  public ContentIndexStatus SaveOcrPage(string id,int page,string text,string expected){var existing=ReadContentChunks(new[]{id}).Where(c=>c.kind=="page"||c.kind=="ocr_page"||c.kind=="ocr").GroupBy(c=>c.anchor.page).ToList();var pages=new List<ContentPage>();foreach(var group in existing.Where(g=>g.Key!=page)){var body=new StringBuilder();foreach(var c in group.OrderBy(c=>c.anchor.start)){int skip=Math.Max(0,body.Length-c.anchor.start);if(skip<c.text.Length)body.Append(c.text.Substring(skip));}pages.Add(new ContentPage{page=group.Key,text=body.ToString(),method=group.First().kind.Contains("ocr")?"ocr":"text"});}pages.Add(new ContentPage{page=page,text=text,method="ocr"});return IndexContentSource(id,pages.OrderBy(p=>p.page).ToList(),expected);}
 }
 internal static class OcrActions {
  internal static IEnumerable<ActionSpec> Actions(){return new[]{ModuleDefinitions.Action("ocrPage",Need.NormalLibrary,true,async(c,a)=>{var item=c.Library.Find(ModuleContext.Text(a,"id"));if(item==null||item.ext!="PDF"&&item.kind!="photo")throw new InvalidDataException("Choose an image or PDF source for OCR.");string stamp=ModuleContext.Text(a,"stamp");if(stamp!=c.Library.ContentStamp(item.id))throw new InvalidDataException("Source changed before OCR; reopen it and retry.");int page=a.ContainsKey("page")?Convert.ToInt32(a["page"]):1;byte[] bytes;if(item.kind=="photo"){if(new FileInfo(item.path).Length>16*1024*1024)throw new InvalidDataException("OCR source is too large.");bytes=File.ReadAllBytes(item.path);}else bytes=Convert.FromBase64String(ModuleContext.Text(a,"imageBase64"));using(c.BeginWrite()){var text=await LocalOcr.Read(bytes,c.AppDirectory,Path.Combine(c.Library.DataDir,"ocr-work"),c.Jobs.CurrentToken);c.Policy.Ensure(Need.NormalLibrary,"workspace");var state=c.Library.SaveOcrPage(item.id,page,ModuleContext.Text(text,"text"),stamp);c.Notify("contentIndexChanged",null);return new{indexed=state,engine=ModuleContext.Text(text,"engine"),language=ModuleContext.Text(text,"language"),characters=ModuleContext.Text(text,"text").Length};}},CapabilitySchema.Obj(CapabilitySchema.Fields("id",CapabilitySchema.Str(32),"stamp",CapabilitySchema.Str(64),"page",new Dictionary<string,object>{{"type","integer"},{"minimum",1},{"maximum",100000}},"imageBase64",CapabilitySchema.Str(22*1024*1024)),new[]{"id","stamp"})),ModuleDefinitions.Action("contentSourceStamp",Need.NormalLibrary,false,(c,a)=>Task.FromResult((object)c.Library.ContentStamp(ModuleContext.Text(a,"id"))),CapabilitySchema.Obj(CapabilitySchema.Fields("id",CapabilitySchema.Str(32)),new[]{"id"}))};}
 }
}
